"""Pixel Arena level pathing: bots walk a tile map painted in primary colors."""

import heapq
import math

Cell = tuple[int, int]  # (row, col)

ENTER_COST = {".": 1, "D": 3, "S": 1, "G": 1}


def find_path(grid: list[str]) -> list[Cell] | None:
    """Cheapest 4-neighbour path from 'S' to 'G', both inclusive.

    '.' floor costs 1 to enter, 'D' door costs 3, '#' is a wall, 'S'/'G' cost 1.
    Return None when G is unreachable.
    """
    tiles = {(r, c): tile for r, row in enumerate(grid) for c, tile in enumerate(row)}
    start = next((cell for cell, tile in tiles.items() if tile == "S"), None)
    goal = next((cell for cell, tile in tiles.items() if tile == "G"), None)
    if start is None or goal is None:
        return None

    best_cost = {start: 0}
    came_from: dict[Cell, Cell] = {}
    frontier = [(0, start)]
    while frontier:
        cost, cell = heapq.heappop(frontier)
        if cell == goal:
            return _rebuild_path(came_from, goal)
        if cost > best_cost[cell]:
            continue  # stale heap entry: a cheaper route was already expanded
        r, c = cell
        for neighbour in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            # Off-map cells (including short rows) and unknown tiles are impassable.
            enter_cost = ENTER_COST.get(tiles.get(neighbour, "#"))
            if enter_cost is None or cost + enter_cost >= best_cost.get(neighbour, math.inf):
                continue
            best_cost[neighbour] = cost + enter_cost
            came_from[neighbour] = cell
            heapq.heappush(frontier, (cost + enter_cost, neighbour))
    return None


def _rebuild_path(came_from: dict[Cell, Cell], goal: Cell) -> list[Cell]:
    path = [goal]
    while path[-1] in came_from:
        path.append(came_from[path[-1]])
    path.reverse()
    return path


