import unittest

from pathfind import find_path


class VisibleTest(unittest.TestCase):
    def test_straight_corridor(self):
        self.assertEqual(find_path(["S..G"]), [(0, 0), (0, 1), (0, 2), (0, 3)])

    def test_detour_beats_door(self):
        # Doors cost 3+3+1=7; the floor detour costs 5.
        path = find_path(["SDDG", "...."])
        self.assertEqual(path, [(0, 0), (1, 0), (1, 1), (1, 2), (1, 3), (0, 3)])

    def test_door_beats_long_detour(self):
        path = find_path(["SDG", ".#.", ".#.", "..."])
        self.assertEqual(path, [(0, 0), (0, 1), (0, 2)])

    def test_walled_off_goal_is_none(self):
        self.assertIsNone(find_path(["S#G"]))

    def test_missing_goal_is_none(self):
        self.assertIsNone(find_path(["S.."]))

    def test_short_row_is_not_walkable(self):
        self.assertEqual(find_path(["S", "...", "G"]), [(0, 0), (1, 0), (2, 0)])


if __name__ == "__main__":
    unittest.main()

